'use strict';

/* Icones: torres do dock, magias da faixa e projeteis.

 * Diferente dos efeitos, estes NAO sao luz -- sao objetos opacos, desenhados
 * normalmente com o alfa que veio do proprio modelo. Por isso moram aqui e
 * nao em vfx.js: la a regra de composicao e 'lighter', aqui e 'source-over',
 * e misturar as duas no mesmo modulo so gera engano na hora de usar.
 *
 * Todos saem aparados pela caixa do que tem tinta e reescalados para o mesmo
 * lado. O modelo desenha cada objeto num tamanho diferente dentro do quadro;
 * sem aparar, a Balista apareceria menor que a Arqueira no mesmo botao.
 *
 * O projetil aponta para a DIREITA, que e o angulo zero do jogo, e sai
 * quadrado para girar na direcao do voo sem deformar.
 */

const ICONES = {
  torre: {
    arqueira: 'data:image/png;base64,',
    glacial: 'data:image/png;base64,',
    altar: 'data:image/png;base64,',
    bombarda: 'data:image/png;base64,',
    templo: 'data:image/png;base64,',
    balista: 'data:image/png;base64,'
  },
  magia: {
    meteoro: 'data:image/png;base64,',
    gelar: 'data:image/png;base64,',
    furia: 'data:image/png;base64,',
    muralha: 'data:image/png;base64,'
  },
  tiro: {
    flecha: 'data:image/png;base64,',
    virote: 'data:image/png;base64,',
    bala: 'data:image/png;base64,',
    lasca: 'data:image/png;base64,',
    orbe: 'data:image/png;base64,',
    runa: 'data:image/png;base64,'
  }
};

const IconSheet = {
  load() {
    this.img = {};
    for (const grupo of Object.keys(ICONES)) {
      this.img[grupo] = {};
      for (const nome of Object.keys(ICONES[grupo])) {
        const i = new Image();
        i.src = ICONES[grupo][nome];
        this.img[grupo][nome] = i;
      }
    }
  },

  /* Devolve a imagem so quando ela ja pode ser desenhada: antes disso o
   * chamador usa o desenho geometrico antigo e o jogo nunca fica vazio. */
  get(grupo, nome) {
    const g = this.img && this.img[grupo];
    const i = g && g[nome];
    return i && i.complete && i.naturalWidth ? i : null;
  },

  /* Onde o dock mostra a torre em CSS, e mais barato usar a data URI direto
   * do que desenhar num canvas so para virar background-image. */
  url(grupo, nome) {
    return (ICONES[grupo] && ICONES[grupo][nome]) || '';
  }
};
